let state = flow.get("masterOperatorControlsState");
if (!state) {
    state = {
        commonActive: null,
        pauseRequested: null,
        pauseState: "-",
        stage: "-",
        last: "Ожидание статуса мастера",
        sealerDonePendingUnload: null,
        sealOnline: null,
        sealBusy: null,
        sealDone: null,
        sealStartOut: null,
        sealCompletionSeq: 0,
        sealPulseMs: 0,
        cmdSeq: 0,
        lastCmd: "—",
        lastUpdate: "ожидание данных"
    };
}

function hasOwn(obj, key) {
    return Object.prototype.hasOwnProperty.call(obj, key);
}

function normalizeTriState(value) {
    if (value === true) return "active";
    if (value === false) return "inactive";
    const text = String(value ?? "").trim().toLowerCase();
    if (["true", "1", "yes", "online", "active"].includes(text)) return "active";
    if (["false", "0", "no", "offline", "inactive"].includes(text)) return "inactive";
    return "unknown";
}

function makeBadge(value, activeText, inactiveText, unknownText) {
    const key = normalizeTriState(value);
    let text = unknownText;
    if (key === "active") text = activeText;
    if (key === "inactive") text = inactiveText;
    return { key, text };
}

const payload = msg.payload;
if (payload && typeof payload === "object") {
    const common = payload.common_cycle;
    if (common && typeof common === "object") {
        if (hasOwn(common, "active")) state.commonActive = common.active;
        if (hasOwn(common, "pause")) state.pauseRequested = common.pause;
        if (hasOwn(common, "pause_state")) state.pauseState = String(common.pause_state || "-");
        if (hasOwn(common, "stage")) state.stage = String(common.stage || "-");
        if (hasOwn(common, "last")) state.last = String(common.last || "-");
        if (hasOwn(common, "sealer_done_pending_unload")) state.sealerDonePendingUnload = common.sealer_done_pending_unload;
    }

    const seal = payload.seal;
    if (seal && typeof seal === "object") {
        if (hasOwn(seal, "online")) state.sealOnline = seal.online;
        if (hasOwn(seal, "busy")) state.sealBusy = seal.busy;
        if (hasOwn(seal, "done")) state.sealDone = seal.done;
        if (hasOwn(seal, "start_out")) state.sealStartOut = seal.start_out;
        if (hasOwn(seal, "completion_seq")) state.sealCompletionSeq = Number(seal.completion_seq || 0);
        if (hasOwn(seal, "pulse_ms")) state.sealPulseMs = Number(seal.pulse_ms || 0);
    }

    if (hasOwn(payload, "cmd_seq")) state.cmdSeq = Number(payload.cmd_seq || 0);
    if (hasOwn(payload, "last_cmd")) {
        const lastCmd = String(payload.last_cmd || "").trim();
        state.lastCmd = lastCmd || "—";
    }
}

if (msg.topic !== "operator/init") {
    state.lastUpdate = new Date().toLocaleString("ru-RU", { hour12: false });
}

flow.set("masterOperatorControlsState", state);

msg.payload = {
    title: "Управление линией",
    subtitle: "Команды отправляются мастеру COM12 через MQTT",
    commandTopic: "fyl/master_com12/cmd",
    lastUpdate: state.lastUpdate,
    cmdSeq: state.cmdSeq,
    lastCmd: state.lastCmd,
    common: {
        active: makeBadge(state.commonActive, "COMMON запущен", "COMMON остановлен", "COMMON: нет данных"),
        pause: makeBadge(state.pauseRequested, "Пауза запрошена", "Пауза не запрошена", "Пауза: нет данных"),
        sealerPendingUnload: makeBadge(state.sealerDonePendingUnload, "Ждет выгрузку из запайщика", "Выгрузка не ожидается", "Выгрузка: нет данных"),
        stage: state.stage,
        pauseState: state.pauseState,
        last: state.last
    },
    seal: {
        online: makeBadge(state.sealOnline, "COM10 на связи", "Нет связи с COM10", "Связь с COM10: нет данных"),
        busy: makeBadge(state.sealBusy, "Ждет DONE / занят", "Свободен", "SEAL: нет данных"),
        done: makeBadge(state.sealDone, "DONE active", "DONE inactive", "DONE: нет данных"),
        startOut: makeBadge(state.sealStartOut, "START импульс идет", "START выключен", "START: нет данных"),
        completionSeq: state.sealCompletionSeq,
        pulseMs: state.sealPulseMs
    }
};

return msg;

