let state = flow.get("operatorMqttLogState");
if (!state || typeof state !== "object") {
    state = {
        enabled: false,
        lines: [],
        lastAction: "Логирование остановлено",
        lastUpdate: "ожидание данных"
    };
}

if (!Array.isArray(state.lines)) {
    state.lines = [];
}

const action = String(msg.payload == null ? "" : msg.payload).trim().toLowerCase();
if (action === "start") {
    state.enabled = true;
    state.lastAction = "Логирование MQTT запущено";
} else if (action === "stop") {
    state.enabled = false;
    state.lastAction = "Логирование MQTT остановлено";
} else if (action === "clear") {
    state.lines = [];
    state.lastAction = "Лог очищен";
}

state.lastUpdate = new Date().toLocaleString("ru-RU", { hour12: false });
flow.set("operatorMqttLogState", state);

msg.payload = {
    enabled: state.enabled,
    lineCount: state.lines.length,
    lastAction: state.lastAction,
    lastUpdate: state.lastUpdate,
    logText: state.lines.join("\n")
};

return msg;

let state = flow.get("operatorMqttLogState");
if (!state || typeof state !== "object") {
    state = {
        enabled: false,
        lines: [],
        lastAction: "Логирование остановлено",
        lastUpdate: "ожидание данных"
    };
}

if (!Array.isArray(state.lines)) {
    state.lines = [];
}

if (!state.enabled) {
    return null;
}

let payloadText = "";
if (typeof msg.payload === "string") {
    payloadText = msg.payload;
} else {
    try {
        payloadText = JSON.stringify(msg.payload);
    } catch (err) {
        payloadText = String(msg.payload);
    }
}

const ts = new Date().toLocaleString("ru-RU", { hour12: false });
const topic = String(msg.topic || "-");
state.lines.push(ts + " | " + topic + " | " + payloadText);

const maxLines = 300;
if (state.lines.length > maxLines) {
    state.lines = state.lines.slice(state.lines.length - maxLines);
}

state.lastUpdate = ts;
flow.set("operatorMqttLogState", state);

msg.payload = {
    enabled: state.enabled,
    lineCount: state.lines.length,
    lastAction: state.lastAction,
    lastUpdate: state.lastUpdate,
    logText: state.lines.join("\n")
};

return msg;
